import React, { useEffect, useState } from "react";
import Navbar from "../Components/Navbar";
import Footer from "../Components/Footer";
import { useParams, useNavigate } from "react-router-dom";
import API_BASE_URL from "../config";
import "../styles/UserPages.css";

const RentalCheckout = () => {
  const { rentalId } = useParams();
  const [rental, setRental] = useState(null);
  const userId = sessionStorage.getItem("userId");
  const navigate = useNavigate();

  useEffect(() => {
    fetch(`${API_BASE_URL}/api/rentals`)
      .then((res) => res.json())
      .then((data) => setRental(data.find((r) => r.id === parseInt(rentalId))));
  }, [rentalId]);

  const handleCheckout = async () => {
    await fetch(`${API_BASE_URL}/api/rentals/checkout`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        user_id: userId,
        rental_id: rental.id,
        total_price: rental.price,
        rental_duration: rental.duration,
      }),
    });
    alert("Rental confirmed!");
    navigate("/rental-orders");
  };

  if (!rental) return <p>Loading...</p>;

  return (
    <>
      <Navbar />
      <div className="page-container">
        <div className="page-header">
          <h2>Confirm Your Rental</h2>
        </div>
        <div className="card">
          {rental.image && <img src={rental.image} alt="Rental" className="card-image" />}
          <h3>{rental.title}</h3>
          <p>{rental.description}</p>
          <p><strong>${rental.price}</strong> / {rental.duration}</p>
          <button className="primary-btn" onClick={handleCheckout}>Confirm Rental</button>
        </div>
      </div>
      <Footer />
    </>
  );
};

export default RentalCheckout;
